//! Hilbert bases of cones by Pottier's algorithm, and the cone data of the Mori cone from them.
//!
//! Given a generating set $B$ of the monoid $C \cap \mathbb{Z}^n$ of a pointed cone $C$ and a
//! linear form $\lambda$, the monoid of $C \cap \{\lambda \ge 0\}$ is generated by the elements
//! of $B$ with $\lambda \ge 0$ and the sums of elements of opposite signs, added until nothing
//! new appears. A sum $z$ is dropped when an element $w$ of the same sign has
//! $|\lambda(w)| \le |\lambda(z)|$ and $z - w \in C$, since then $z = w + (z - w)$ with
//! $z - w$ in the new cone (the dual algorithm of Normaliz, as Bruns and Ichim describe it).
//! The reduction is only sound for a pointed $C$, so the first cone is the simplicial one of
//! $n$ of the facets, whose Hilbert basis is among its rays and the lattice points of their
//! half-open parallelepiped; then come the other facets. Cutting the Mori cone's basis by the
//! rows $Q_r$ gives the cones $K_T$, and there sums of degree above the maximum are dropped,
//! which is sound since every cone then lies in the Mori cone, where the grading is positive.
//!
//! A face of the Mori cone, cut out by equations, is handled in a basis of the lattice of its
//! span, where it is full-dimensional.
//!
//! This replaced Normaliz for the cone data in phase 7b of `PLAN.md`, which records the
//! comparison with enumerating the lattice points of the cones directly.

use super::{columns, CandidateCone, ConeData, TooLarge};
use crate::Stratum;
use nalgebra::DMatrix;
use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashSet};
use std::fmt;

/// Why the Hilbert bases could not be computed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConeError {
    /// The cone contains a line, so it has no Hilbert basis in this sense, and is no Mori cone.
    NotPointed,
    /// The grading vector is not positive on every nonzero point of the cone.
    NonpositiveDegree,
    /// An entry overflowed (see [`TooLarge`]), or the simplicial cone that the computation
    /// starts from has more lattice points in its fundamental parallelepiped than it allows.
    TooLarge,
}

impl fmt::Display for ConeError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::NotPointed => write!(f, "the Mori cone contains a line"),
            Self::NonpositiveDegree => write!(
                f,
                "the grading vector must be positive on every nonzero point of the Mori cone"
            ),
            Self::TooLarge => write!(f, "the Hilbert bases of the Mori cone are too large"),
        }
    }
}

impl std::error::Error for ConeError {}

impl From<TooLarge> for ConeError {
    fn from(_: TooLarge) -> Self {
        Self::TooLarge
    }
}

/// The largest fundamental parallelepiped the computation starts from.
const MAX_PARALLELEPIPED: i128 = 1 << 22;

fn add(a: i64, b: i64) -> Result<i64, TooLarge> {
    a.checked_add(b).ok_or(TooLarge)
}

fn dot(a: &[i64], b: &[i64]) -> Result<i64, TooLarge> {
    a.iter().zip(b).try_fold(0i64, |s, (&x, &y)| {
        x.checked_mul(y)
            .and_then(|p| s.checked_add(p))
            .ok_or(TooLarge)
    })
}

fn gcd(a: i128, b: i128) -> i128 {
    if b == 0 {
        a.abs()
    } else {
        gcd(b, a % b)
    }
}

/// An element of the monoid, with its values under the inequalities cut so far.
#[derive(Clone, Debug)]
struct Elem {
    x: Vec<i64>,
    y: Vec<i64>,
}

/// Whether $z - w$ satisfies every inequality cut so far.
fn below(w: &Elem, z: &Elem) -> bool {
    w.y.iter().zip(&z.y).all(|(a, b)| a <= b)
}

/// The Hilbert basis of the monoid generated by `elems` in a pointed cone, i.e. those not
/// above another one, sorted by the sum of their values under the inequalities.
fn minimize(mut elems: Vec<Elem>) -> Vec<Elem> {
    elems.sort_by_cached_key(|e| (e.y.iter().map(|&v| v as i128).sum::<i128>(), e.x.clone()));
    let mut kept: Vec<Elem> = Vec::new();
    for z in elems {
        if !kept.iter().any(|w| below(w, &z)) {
            kept.push(z);
        }
    }
    kept
}

/// The Hilbert basis of the pointed cone with Hilbert basis `basis` cut by $\lambda \ge 0$,
/// without the elements of degree above `truncate.1` under `truncate.0` if given (sound only
/// when the grading is positive on the cone).
fn cut(
    basis: &[Elem],
    lambda: &[i64],
    truncate: Option<(&[i64], i64)>,
) -> Result<Vec<Elem>, TooLarge> {
    let k = basis.first().map_or(0, |e| e.y.len());
    let (mut pos, mut neg, mut zero) = (Vec::new(), Vec::new(), Vec::new());
    for e in basis {
        if let Some((w, d)) = truncate {
            if dot(w, &e.x)? > d {
                continue;
            }
        }
        let l = dot(lambda, &e.x)?;
        let mut e = e.clone();
        e.y.push(l);
        match l.signum() {
            1 => pos.push(e),
            -1 => neg.push(e),
            _ => zero.push(e),
        }
    }
    // The pairs by the size of their sum, smallest first, so that reducers tend to come before
    // the elements they reduce.
    let size = |e: &Elem| -> Result<i64, TooLarge> {
        match truncate {
            Some((w, _)) => dot(w, &e.x),
            None => Ok(e.y[..k].iter().sum()),
        }
    };
    let mut heap = BinaryHeap::new();
    for (i, p) in pos.iter().enumerate() {
        for (j, q) in neg.iter().enumerate() {
            heap.push(Reverse((add(size(p)?, size(q)?)?, i, j)));
        }
    }
    while let Some(Reverse((_, i, j))) = heap.pop() {
        let (p, q) = (&pos[i], &neg[j]);
        let x = (p.x.iter().zip(&q.x))
            .map(|(&a, &b)| add(a, b))
            .collect::<Result<Vec<_>, _>>()?;
        if x.iter().all(|&v| v == 0) {
            continue;
        }
        if let Some((w, d)) = truncate {
            if dot(w, &x)? > d {
                continue;
            }
        }
        let y = (p.y.iter().zip(&q.y))
            .map(|(&a, &b)| add(a, b))
            .collect::<Result<Vec<_>, _>>()?;
        let z = Elem { x, y };
        let l = z.y[k];
        // An element of the same sign with |lambda| no larger, and no larger under every old
        // inequality, i.e. with z - w in the old cone.
        let reducible = |set: &[Elem]| {
            set.iter().any(|w| {
                w.y[k].abs() <= l.abs() && w.y[..k].iter().zip(&z.y[..k]).all(|(a, b)| a <= b)
            })
        };
        match l.signum() {
            1 if !reducible(&pos) => {
                let s = size(&z)?;
                pos.push(z);
                for (j, q) in neg.iter().enumerate() {
                    heap.push(Reverse((add(s, size(q)?)?, pos.len() - 1, j)));
                }
            }
            -1 if !reducible(&neg) => {
                let s = size(&z)?;
                neg.push(z);
                for (i, p) in pos.iter().enumerate() {
                    heap.push(Reverse((add(s, size(p)?)?, i, neg.len() - 1)));
                }
            }
            0 if !reducible(&zero) => zero.push(z),
            _ => {}
        }
    }
    Ok(minimize(pos.into_iter().chain(zero).collect()))
}

/// The rank of a set of integer vectors.
pub(crate) fn rank(rows: &[Vec<i64>]) -> usize {
    let mut a: Vec<Vec<i128>> = rows
        .iter()
        .map(|r| r.iter().map(|&x| x as i128).collect())
        .collect();
    let n = a.first().map_or(0, Vec::len);
    let mut r = 0;
    for c in 0..n {
        let Some(p) = (r..a.len()).find(|&i| a[i][c] != 0) else {
            continue;
        };
        a.swap(r, p);
        for i in r + 1..a.len() {
            if a[i][c] != 0 {
                let (s, t) = (a[r][c], a[i][c]);
                let g = gcd(s, t);
                let pivot = a[r].clone();
                a[i].iter_mut()
                    .zip(&pivot)
                    .for_each(|(x, y)| *x = s / g * *x - t / g * y);
                let h = a[i].iter().fold(0, |h, &x| gcd(h, x));
                if h > 1 {
                    a[i].iter_mut().for_each(|x| *x /= h);
                }
            }
        }
        r += 1;
    }
    r
}

/// The determinant of a square integer matrix, by Bareiss's fraction-free elimination.
pub(crate) fn det(m: &[Vec<i64>]) -> Result<i128, TooLarge> {
    let n = m.len();
    if n == 0 {
        return Ok(1);
    }
    let mut a: Vec<Vec<i128>> = m
        .iter()
        .map(|r| r.iter().map(|&x| x as i128).collect())
        .collect();
    let (mut sign, mut prev) = (1, 1i128);
    for c in 0..n {
        let Some(p) = (c..n).find(|&i| a[i][c] != 0) else {
            return Ok(0);
        };
        if p != c {
            a.swap(p, c);
            sign = -sign;
        }
        for i in c + 1..n {
            for j in c + 1..n {
                let v = a[i][j]
                    .checked_mul(a[c][c])
                    .zip(a[i][c].checked_mul(a[c][j]))
                    .and_then(|(x, y)| x.checked_sub(y))
                    .ok_or(TooLarge)?;
                a[i][j] = v / prev;
            }
        }
        prev = a[c][c];
    }
    Ok(sign * a[n - 1][n - 1])
}

/// The adjugate of a square integer matrix: $\operatorname{adj}(m)\, m = \det(m)\, I$.
fn adjugate(m: &[Vec<i64>]) -> Result<Vec<Vec<i128>>, TooLarge> {
    let n = m.len();
    (0..n)
        .map(|i| {
            (0..n)
                .map(|j| {
                    let minor: Vec<Vec<i64>> = (0..n)
                        .filter(|&r| r != j)
                        .map(|r| (0..n).filter(|&c| c != i).map(|c| m[r][c]).collect())
                        .collect();
                    let sign = if (i + j) % 2 == 0 { 1 } else { -1 };
                    Ok(sign * det(&minor)?)
                })
                .collect()
        })
        .collect()
}

/// A basis of the lattice of integer vectors orthogonal to all of `equations`, by unimodular
/// column operations on the identity.
pub(crate) fn kernel_basis(equations: &[Vec<i64>], n: usize) -> Result<Vec<Vec<i64>>, TooLarge> {
    let mut cols: Vec<Vec<i64>> = (0..n)
        .map(|i| (0..n).map(|j| (i == j) as i64).collect())
        .collect();
    let mut k = 0;
    for e in equations {
        // The values of the equation on the columns not used yet, made all zero but one by
        // Euclid's algorithm.
        let mut v: Vec<i64> = cols.iter().map(|c| dot(e, c)).collect::<Result<_, _>>()?;
        loop {
            let nonzero: Vec<usize> = (k..n).filter(|&j| v[j] != 0).collect();
            let Some(&i) = nonzero.iter().min_by_key(|&&j| v[j].unsigned_abs()) else {
                break;
            };
            if nonzero.len() == 1 {
                cols.swap(k, i);
                v.swap(k, i);
                k += 1;
                break;
            }
            for &j in nonzero.iter().filter(|&&j| j != i) {
                let q = v[j].div_euclid(v[i]);
                v[j] -= q * v[i];
                let ci = cols[i].clone();
                for (a, b) in cols[j].iter_mut().zip(&ci) {
                    *a = b
                        .checked_mul(q)
                        .and_then(|p| a.checked_sub(p))
                        .ok_or(TooLarge)?;
                }
            }
        }
    }
    Ok(cols.split_off(k))
}

/// Coordinates $t$ on the lattice of the span of a cone, $x = U t$ for a basis $U$.
struct Coordinates {
    n: usize,
    basis: Vec<Vec<i64>>,
}

impl Coordinates {
    fn new(n: usize, equations: &DMatrix<i32>) -> Result<Self, TooLarge> {
        let eqs: Vec<Vec<i64>> = columns(equations).map(widen).collect();
        Ok(Self {
            n,
            basis: kernel_basis(&eqs, n)?,
        })
    }

    /// A linear form in the coordinates $t$.
    fn form(&self, f: &[i64]) -> Result<Vec<i64>, TooLarge> {
        self.basis.iter().map(|b| dot(f, b)).collect()
    }

    /// The vectors $x = U t$, as the columns of a matrix, sorted.
    fn matrix(&self, ts: &[Elem]) -> Result<DMatrix<i32>, TooLarge> {
        let mut xs = ts
            .iter()
            .map(|t| {
                (0..self.n)
                    .map(|i| {
                        let x = self.basis.iter().zip(&t.x).try_fold(0i64, |s, (b, &c)| {
                            b[i].checked_mul(c).and_then(|p| s.checked_add(p))
                        });
                        x.and_then(|x| i32::try_from(x).ok()).ok_or(TooLarge)
                    })
                    .collect::<Result<Vec<_>, _>>()
            })
            .collect::<Result<Vec<_>, _>>()?;
        xs.sort();
        Ok(DMatrix::from_vec(self.n, xs.len(), xs.concat()))
    }
}

fn widen(v: &[i32]) -> Vec<i64> {
    v.iter().map(|&x| x as i64).collect()
}

/// The Hilbert basis of the full-dimensional pointed cone $\{h \cdot t \ge 0\}$ in $d$
/// dimensions.
fn basis_full(hyperplanes: &[Vec<i64>], d: usize) -> Result<Vec<Elem>, ConeError> {
    // d independent hyperplanes, the first ones found.
    let mut chosen: Vec<usize> = Vec::new();
    for i in 0..hyperplanes.len() {
        if chosen.len() == d {
            break;
        }
        let rows: Vec<Vec<i64>> = chosen
            .iter()
            .chain([&i])
            .map(|&k| hyperplanes[k].clone())
            .collect();
        if rank(&rows) > chosen.len() {
            chosen.push(i);
        }
    }
    if chosen.len() < d {
        return Err(ConeError::NotPointed);
    }
    let h: Vec<Vec<i64>> = chosen.iter().map(|&k| hyperplanes[k].clone()).collect();
    // The rays of {h_i . t >= 0} are the columns of adj(h), times the sign of det(h).
    let adj = adjugate(&h)?;
    let sign = det(&h)?.signum();
    let mut rays: Vec<Vec<i64>> = (0..d)
        .map(|j| {
            let r: Vec<i128> = (0..d).map(|i| adj[i][j] * sign).collect();
            let g = r.iter().fold(0, |g, &x| gcd(g, x));
            r.iter()
                .map(|&x| i64::try_from(x / g).map_err(|_| TooLarge))
                .collect::<Result<Vec<_>, _>>()
        })
        .collect::<Result<_, _>>()?;
    // The points of the half-open parallelepiped of the rays: Z^d modulo the lattice of the
    // rays, a group of order D = |det(rays)| whose element c stands for sum c_j r_j / D.
    let r: Vec<Vec<i64>> = (0..d)
        .map(|i| (0..d).map(|j| rays[j][i]).collect())
        .collect();
    let rdet = det(&r)?;
    let big_d = rdet.abs();
    if big_d > MAX_PARALLELEPIPED {
        return Err(ConeError::TooLarge);
    }
    let radj = adjugate(&r)?;
    // The unit vectors, e_i = sum_j (R^-1)_ji r_j, generate the group.
    let gens: Vec<Vec<i128>> = (0..d)
        .map(|i| {
            (0..d)
                .map(|j| (radj[j][i] * rdet.signum()).rem_euclid(big_d))
                .collect()
        })
        .collect();
    let zero = vec![0i128; d];
    let mut seen = HashSet::from([zero.clone()]);
    let mut stack = vec![zero];
    while let Some(c) = stack.pop() {
        for g in &gens {
            let e: Vec<i128> = c.iter().zip(g).map(|(a, b)| (a + b) % big_d).collect();
            if seen.insert(e.clone()) {
                stack.push(e);
            }
        }
    }
    for c in seen.into_iter().filter(|c| c.iter().any(|&x| x != 0)) {
        let x = (0..d)
            .map(|i| {
                let v: i128 = (0..d).map(|j| c[j] * rays[j][i] as i128).sum();
                i64::try_from(v / big_d).map_err(|_| TooLarge)
            })
            .collect::<Result<Vec<_>, _>>()?;
        rays.push(x);
    }
    let elems = rays
        .into_iter()
        .map(|x| {
            let y = h.iter().map(|hi| dot(hi, &x)).collect::<Result<_, _>>()?;
            Ok(Elem { x, y })
        })
        .collect::<Result<Vec<_>, TooLarge>>()?;
    let mut elems = minimize(elems);
    for (i, hi) in hyperplanes.iter().enumerate() {
        if !chosen.contains(&i) {
            elems = cut(&elems, hi, None)?;
        }
    }
    Ok(elems)
}

/// The Hilbert basis of the monoid of lattice points of the pointed cone cut out by the
/// columns of `hyperplanes` ($h \cdot C \ge 0$) and `equations` ($e \cdot C = 0$), which must
/// have the same number of rows, one element per column, sorted lexicographically. Redundant
/// hyperplanes are allowed.
pub fn hilbert_basis(
    hyperplanes: &DMatrix<i32>,
    equations: &DMatrix<i32>,
) -> Result<DMatrix<i32>, ConeError> {
    let n = hyperplanes.nrows().max(equations.nrows());
    let coords = Coordinates::new(n, equations)?;
    let hs = columns(hyperplanes)
        .map(|h| coords.form(&widen(h)))
        .collect::<Result<Vec<_>, _>>()?;
    let basis = basis_full(&hs, coords.basis.len())?;
    Ok(coords.matrix(&basis)?)
}

/// The cone data of the pointed Mori cone cut out by the columns of `hyperplanes` and
/// `equations`: those, and the Hilbert basis of the cone $K_T$ of every set $T$ of one or two
/// divisors and of the divisors of every stratum, without its elements of degree above
/// `max_deg` under `grading_vector`, which must be positive on the Mori cone. `q` has one row
/// per divisor.
///
/// The cones are nested, $K_T \subset K_{T'}$ for $T \subset T'$, so they are computed down a
/// tree: from the Mori cone's basis, cut by each row $Q_r$ in turn or not, with at most two
/// rows left out (three for a stratum).
pub fn cone_data(
    hyperplanes: &DMatrix<i32>,
    equations: &DMatrix<i32>,
    q: &DMatrix<i32>,
    strata: &[Stratum],
    grading_vector: &[i32],
    max_deg: u32,
) -> Result<ConeData, ConeError> {
    let n = grading_vector.len();
    let coords = Coordinates::new(n, equations)?;
    let hs = columns(hyperplanes)
        .map(|h| coords.form(&widen(h)))
        .collect::<Result<Vec<_>, _>>()?;
    let mori = basis_full(&hs, coords.basis.len())?;
    let w = coords.form(&widen(grading_vector))?;
    let mut basis = Vec::with_capacity(mori.len());
    for e in mori {
        let deg = dot(&w, &e.x)?;
        if deg <= 0 {
            return Err(ConeError::NonpositiveDegree);
        }
        if deg <= max_deg as i64 {
            basis.push(e);
        }
    }
    let rows = (0..q.nrows())
        .map(|r| coords.form(&q.row(r).iter().map(|&x| x as i64).collect::<Vec<_>>()))
        .collect::<Result<Vec<_>, _>>()?;
    let strata: Vec<[usize; 3]> = strata
        .iter()
        .map(|s| {
            let mut d = s.divisors;
            d.sort_unstable();
            d
        })
        .collect();
    let tree = Tree {
        rows: &rows,
        w: &w,
        max_deg: max_deg as i64,
        strata: &strata,
    };
    let mut found = Vec::new();
    tree.descend(0, basis, &mut Vec::new(), &mut found)?;
    let cones = found
        .into_iter()
        .map(|(divisors, basis)| {
            Ok(CandidateCone {
                divisors,
                hilbert_basis: coords.matrix(&basis)?,
            })
        })
        .collect::<Result<Vec<_>, TooLarge>>()?;
    Ok(ConeData {
        hyperplanes: hyperplanes.clone(),
        equations: equations.clone(),
        cones,
    })
}

/// The tree of cuts that gives the cones $K_T$.
struct Tree<'a> {
    /// The rows $Q_r$, in the coordinates of the span.
    rows: &'a [Vec<i64>],
    /// The grading vector, in the coordinates of the span.
    w: &'a [i64],
    max_deg: i64,
    /// The divisors of the strata, in increasing order.
    strata: &'a [[usize; 3]],
}

impl Tree<'_> {
    /// Whether the divisors left out so far, in increasing order, can still be a set that
    /// needs a cone.
    fn may_skip(&self, skipped: &[usize]) -> bool {
        skipped.len() <= 2
            || self
                .strata
                .iter()
                .any(|s| skipped.iter().all(|r| s.contains(r)))
    }

    /// Cuts `basis` by the rows from `r` on, except those it leaves out, and collects the
    /// cones of the sets of divisors left out that need one.
    fn descend(
        &self,
        r: usize,
        basis: Vec<Elem>,
        skipped: &mut Vec<usize>,
        found: &mut Vec<(Vec<usize>, Vec<Elem>)>,
    ) -> Result<(), TooLarge> {
        if r == self.rows.len() {
            let needed = match skipped.len() {
                0 => false,
                1 | 2 => true,
                _ => self.strata.iter().any(|s| s[..] == skipped[..]),
            };
            if needed {
                found.push((skipped.clone(), basis));
            }
            return Ok(());
        }
        skipped.push(r);
        if self.may_skip(skipped) {
            self.descend(r + 1, basis.clone(), skipped, found)?;
        }
        skipped.pop();
        let cut = cut(&basis, &self.rows[r], Some((self.w, self.max_deg)))?;
        self.descend(r + 1, cut, skipped, found)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use nalgebra::dmatrix;

    fn cols(m: &DMatrix<i32>) -> Vec<Vec<i32>> {
        columns(m).map(<[i32]>::to_vec).collect()
    }

    /// The Hilbert basis of the pointed cone of `hyperplanes` and `equations` by brute force:
    /// the irreducible points among those with every coordinate at most `bound` in absolute
    /// value.
    fn brute_force(hyperplanes: &[Vec<i32>], equations: &[Vec<i32>], bound: i32) -> Vec<Vec<i32>> {
        let n = hyperplanes[0].len();
        let inside = |x: &[i32]| {
            hyperplanes
                .iter()
                .all(|h| dot(&widen(h), &widen(x)).unwrap() >= 0)
                && equations
                    .iter()
                    .all(|e| dot(&widen(e), &widen(x)).unwrap() == 0)
        };
        let mut points: Vec<Vec<i32>> = vec![vec![]];
        for _ in 0..n {
            points = points
                .into_iter()
                .flat_map(|p| (-bound..=bound).map(move |v| [&p[..], &[v]].concat()))
                .collect();
        }
        points.retain(|p| p.iter().any(|&v| v != 0) && inside(p));
        let set: HashSet<&Vec<i32>> = points.iter().collect();
        let mut basis: Vec<Vec<i32>> = points
            .iter()
            .filter(|z| {
                !points.iter().any(|w| {
                    let d: Vec<i32> = z.iter().zip(w).map(|(a, b)| a - b).collect();
                    w != *z && set.contains(&d)
                })
            })
            .cloned()
            .collect();
        basis.sort();
        basis
    }

    #[test]
    fn test_hilbert_basis() {
        // The cone of (1, 0) and (1, 2), whose basis adds (1, 1), and that of (1, 0) and
        // (1, 3), which adds two.
        let b = hilbert_basis(&dmatrix![0, 2; 1, -1], &DMatrix::zeros(2, 0)).unwrap();
        assert_eq!(cols(&b), [[1, 0], [1, 1], [1, 2]]);
        let b = hilbert_basis(&dmatrix![0, 3; 1, -1], &DMatrix::zeros(2, 0)).unwrap();
        assert_eq!(cols(&b), [[1, 0], [1, 1], [1, 2], [1, 3]]);
        // A ray, and the face of (1, 0, 1) and (1, 2, 1) on x = z.
        let b = hilbert_basis(&dmatrix![1; 2], &dmatrix![2; -1]).unwrap();
        assert_eq!(cols(&b), [[1, 2]]);
        let b = hilbert_basis(&dmatrix![0, 2; 1, -1; 0, 0], &dmatrix![1; 0; -1]).unwrap();
        assert_eq!(cols(&b), [[1, 0, 1], [1, 1, 1], [1, 2, 1]]);
        // A half-plane is not pointed.
        assert_eq!(
            hilbert_basis(&dmatrix![0; 1], &DMatrix::zeros(2, 0)),
            Err(ConeError::NotPointed)
        );
    }

    /// Random pointed cones in dimensions 2 and 3, some on a plane, against the brute force.
    #[test]
    fn test_random_cones() {
        let mut state = 0x853c49e6748fea9bu64;
        let mut next = |m: u64| {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state % m
        };
        let mut sizes = HashSet::new();
        for n in 2..=3 {
            for _ in 0..60 {
                // Generators with a positive first coordinate, so that the cone is pointed.
                let count = 2 + next(4) as usize;
                let on_plane = n == 3 && next(2) == 0;
                let gens: Vec<i32> = (0..count)
                    .flat_map(|_| {
                        let mut g: Vec<i32> = (0..n).map(|_| next(7) as i32 - 3).collect();
                        g[0] = 1 + next(3) as i32;
                        if on_plane {
                            g[n - 1] = g[0];
                        }
                        g
                    })
                    .collect();
                let gens = DMatrix::from_vec(n, count, gens);
                let f = super::super::facets(&gens).unwrap();
                let b = hilbert_basis(&f.hyperplanes, &f.equations).unwrap();
                // The basis lies in the parallelepipeds of the generators, so its coordinates
                // are at most n times 3 in absolute value.
                let expected =
                    brute_force(&cols(&f.hyperplanes), &cols(&f.equations), 3 * n as i32);
                assert_eq!(cols(&b), expected, "{gens}");
                sizes.insert(b.ncols());
            }
        }
        // Not only simplicial cones with unimodular starts.
        assert!(sizes.iter().any(|&s| s > 4));
    }

    #[test]
    fn test_cone_data() {
        // P(1,1,2,2,2)[8], whose sixth divisor is negative on the curves (x, y) with x < 2y:
        // every cone with it is the Mori cone, the others are spanned by (1, 0) and (2, 1).
        let q = DMatrix::from_row_slice(6, 2, &[0, 1, 0, 1, 1, 0, 1, 0, 1, 0, 1, -2]);
        let mori = dmatrix![1, 0; 0, 1];
        let none = DMatrix::zeros(2, 0);
        let cd = cone_data(&mori, &none, &q, &[], &[1, 1], 10).unwrap();
        assert_eq!(cd.cones.len(), 21);
        for c in &cd.cones {
            let expected = if c.divisors.contains(&5) {
                [[0, 1], [1, 0]]
            } else {
                [[1, 0], [2, 1]]
            };
            assert_eq!(cols(&c.hilbert_basis), expected, "{:?}", c.divisors);
        }
        // Truncated, and with a stratum on the divisors 0, 1 and 5.
        let strata = [Stratum {
            divisors: [5, 1, 0],
            class: vec![1.into(), 0.into()],
        }];
        let cd = cone_data(&mori, &none, &q, &strata, &[1, 1], 2).unwrap();
        assert_eq!(cd.cones.len(), 22);
        let k01 = cd.cones.iter().find(|c| c.divisors == [0, 1]).unwrap();
        assert_eq!(cols(&k01.hilbert_basis), [[1, 0]]);
        assert!(cd.cones.iter().any(|c| c.divisors == [0, 1, 5]));
        // The grading must be positive on the cone.
        assert_eq!(
            cone_data(&mori, &none, &q, &[], &[1, 0], 2).err(),
            Some(ConeError::NonpositiveDegree)
        );
    }
}
